content.content:
		}
		return strings.Join(append(parts, theme.EmptyLineBg(width), infoLine), "\n")
	}

	if m.showsTree() {
		var parts []string
		if bar := m.table.FilterBar(); bar.IsVisible() {
			parts = append(parts, bar.View())
		}
		parts = append(parts, m.renderTabBar(), theme.EmptyLineBg(width), infoLine)
